package com.nigson.integration.carrier;

import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.*;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;
import com.nigson.integration.platform.AuditWriter;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.ProviderHttp;
import io.micrometer.core.instrument.MeterRegistry;

/** Tracking retains completed creation evidence; only short owner-local transactions acquire locks. */
public final class CarrierTrackingExecution {
 public record Claim(UUID bookingId,UUID jobId,UUID shipmentId,UUID correlation,long bookingVersion,long jobVersion,Instant lease,String mode,String tracking,boolean compatible,JsonNode checkpoint){
  public Claim{checkpoint=checkpoint.deepCopy();}
  @Override public JsonNode checkpoint(){return checkpoint.deepCopy();}
  @Override public String toString(){return "CarrierTrackingClaim[protected]";}
 }
 private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final AuditWriter audit;private final Clock clock;private final MeterRegistry metrics;private final String mode,account;
 public CarrierTrackingExecution(JdbcTemplate jdbc,PlatformTransactionManager manager,AuditWriter audit,Clock clock,ProviderHttp.Mode mode,String account,MeterRegistry metrics){this.jdbc=Objects.requireNonNull(jdbc);this.audit=Objects.requireNonNull(audit);this.clock=Objects.requireNonNull(clock);this.metrics=Objects.requireNonNull(metrics);if(mode==null||account==null||!account.matches("[a-f0-9]{64}"))throw new IllegalArgumentException("CARRIER_TRACKING_IDENTITY_REQUIRED");this.mode=mode==ProviderHttp.Mode.TEST?"SANDBOX":mode.name();this.account=account;tx=new TransactionTemplate(manager);tx.setTimeout(5);}
 private java.sql.Timestamp stamp(Instant value){return java.sql.Timestamp.from(value);}
 private void local(){jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.execute("SET LOCAL statement_timeout='2s'");}
 private static long version(Map<String,Object> row){return ((Number)row.get("version")).longValue();}
 private Claim claim(Map<String,Object> b,Map<String,Object> j){var cursor=EventCodec.JSON.readTree(j.get("cursor").toString());boolean compatible=CarrierBookingExecution.checkpoint(cursor)&&"COMPLETE".equals(cursor.path("stage").asString())&&cursor.has("pieceTrackingNumbers")&&mode.equals(b.get("mode"))&&account.equals(cursor.path("accountHash").asString())&&Objects.equals(b.get("tracking_number"),cursor.path("trackingNumber").asString())&&Objects.equals(b.get("request_hash"),cursor.path("requestHash").asString())&&validTracking(cursor.path("tracking"))&&(!cursor.path("tracking").has("pending")||mode.equals(cursor.path("tracking").path("pending").path("mode").asString())&&Objects.equals(b.get("tracking_number"),cursor.path("tracking").path("pending").path("reference").asString()));UUID correlation=compatible?ApiValues.uuid(cursor.path("correlationId").asString()):UUID.randomUUID();return new Claim((UUID)b.get("id"),(UUID)j.get("id"),(UUID)b.get("shipment_id"),correlation,version(b),version(j),((java.sql.Timestamp)b.get("lease_until")).toInstant(),b.get("mode").toString(),Objects.toString(b.get("tracking_number"),""),compatible,cursor);}
 private static boolean validTracking(JsonNode tracking){if(tracking.isMissingNode())return true;try{if(!tracking.isObject()||!Set.of("last","pending").containsAll(tracking.propertyNames()))return false;if(tracking.has("last")){var last=tracking.path("last");if(!last.propertyNames().equals(Set.of("status","occurredAt"))||!Set.of("SHIPPED","DELIVERED","CANCELLED","EXCEPTION").contains(last.path("status").asString()))return false;Instant.parse(last.path("occurredAt").asString());}if(tracking.has("pending")){var body=tracking.path("pending");if(!body.propertyNames().equals(Set.of("commandId","provider","reference","status","occurredAt","mode"))||!"FEDEX".equals(body.path("provider").asString())||!Set.of("SHIPPED","DELIVERED","CANCELLED","EXCEPTION").contains(body.path("status").asString()))return false;ApiValues.uuid(body.path("commandId").asString());Instant.parse(body.path("occurredAt").asString());for(var value:body)if(!value.isString())return false;}return true;}catch(RuntimeException invalid){return false;}}
 private void audit(Claim c,String state){audit(c,state,c.bookingVersion(),c.bookingVersion()+1);}
 private void audit(Claim c,String state,long before,long after){audit.append("integration-carrier-tracking",AuditValues.ActorKind.SYSTEM,AuditValues.Action.QUEUE_REPLAY,AuditValues.Resource.QUEUE,c.jobId(),c.correlation(),AuditValues.Reason.RECONCILIATION,Map.of("version",before),Map.of("version",after),null);TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){metrics.counter("nigson.integration.carrier.tracking","state",state).increment();}});}
 public Optional<Claim> claim(){return claim(null);}
 public Optional<Claim> claim(UUID shipment){return tx.execute(status->{local();var rows=jdbc.queryForList("SELECT b.* FROM integration.carrier_booking b JOIN integration.integration_job j ON j.business_key=b.business_key AND j.resource_id=b.shipment_id AND j.owner_service='commerce' AND j.kind='LOGISTICS_CREATE' AND j.state='SUCCEEDED' WHERE (?::uuid IS NULL OR b.shipment_id=?) AND b.provider='FEDEX' AND b.state='BOOKED' AND b.next_poll_at<=? AND (b.lease_until IS NULL OR b.lease_until<=?) ORDER BY b.next_poll_at,b.id FOR UPDATE OF b SKIP LOCKED LIMIT 1",shipment,shipment,stamp(clock.instant()),stamp(clock.instant()));if(rows.isEmpty())return Optional.empty();var b=rows.getFirst();var jobs=jdbc.queryForList("SELECT * FROM integration.integration_job WHERE business_key=? FOR UPDATE SKIP LOCKED",b.get("business_key"));if(jobs.isEmpty())return Optional.empty();var j=jobs.getFirst();jdbc.update("UPDATE integration.carrier_booking SET lease_until=?,version=version+1,updated_at=?,updated_by='integration-carrier-tracking' WHERE id=?",stamp(clock.instant().plusSeconds(120)),stamp(clock.instant()),b.get("id"));jdbc.update("UPDATE integration.integration_job SET version=version+1,updated_at=?,updated_by='integration-carrier-tracking' WHERE id=?",stamp(clock.instant()),j.get("id"));var result=claim(jdbc.queryForMap("SELECT * FROM integration.carrier_booking WHERE id=?",b.get("id")),jdbc.queryForMap("SELECT * FROM integration.integration_job WHERE id=?",j.get("id")));audit(result,"CLAIMED",version(b),result.bookingVersion());return Optional.of(result);});}
 private boolean lock(Claim c){local();var books=jdbc.queryForList("SELECT * FROM integration.carrier_booking WHERE id=? FOR UPDATE",c.bookingId());if(books.isEmpty())return false;var jobs=jdbc.queryForList("SELECT * FROM integration.integration_job WHERE id=? FOR UPDATE",c.jobId());if(jobs.isEmpty())return false;var b=books.getFirst();var j=jobs.getFirst();return version(b)==c.bookingVersion()&&version(j)==c.jobVersion()&&"BOOKED".equals(b.get("state"))&&"SUCCEEDED".equals(j.get("state"))&&b.get("lease_until")!=null&&((java.sql.Timestamp)b.get("lease_until")).toInstant().isAfter(clock.instant())&&b.get("business_key").equals(j.get("business_key"))&&c.shipmentId().equals(b.get("shipment_id"))&&c.shipmentId().equals(j.get("resource_id"))&&"commerce".equals(j.get("owner_service"))&&"LOGISTICS_CREATE".equals(j.get("kind"))&&c.mode().equals(b.get("mode"))&&c.tracking().equals(b.get("tracking_number"))&&EventCodec.JSON.readTree(j.get("cursor").toString()).equals(c.checkpoint());}
 public Optional<Claim> prepare(Claim c,CarrierTrackingValues.Observation observation){if(!c.compatible()||observation==null||observation.occurredAt()==null||observation.occurredAt().isAfter(clock.instant().plusSeconds(5))||observation.status()!=null&&!Set.of("SHIPPED","DELIVERED","CANCELLED","EXCEPTION").contains(observation.status()))throw CarrierValues.rule();return tx.execute(status->{if(!lock(c))return Optional.empty();var cursor=(ObjectNode)c.checkpoint();var tracking=cursor.has("tracking")?(ObjectNode)cursor.path("tracking"):EventCodec.JSON.createObjectNode();if(tracking.has("pending"))throw CarrierValues.rule();var last=tracking.path("last");if(observation.status()==null||last.isObject()&&(observation.occurredAt().isBefore(Instant.parse(last.path("occurredAt").asString()))||observation.occurredAt().equals(Instant.parse(last.path("occurredAt").asString()))&&observation.status().equals(last.path("status").asString()))){release(c,null,null);return Optional.empty();}var body=EventCodec.JSON.valueToTree(Map.of("commandId",EventCodec.uuid7(clock.instant()).toString(),"provider","FEDEX","reference",c.tracking(),"status",observation.status(),"occurredAt",observation.occurredAt().toString(),"mode",c.mode()));tracking.set("pending",body);cursor.set("tracking",tracking);jdbc.update("UPDATE integration.integration_job SET cursor=?::jsonb,version=version+1,updated_at=?,updated_by='integration-carrier-tracking' WHERE id=?",EventCodec.JSON.writeValueAsString(cursor),stamp(clock.instant()),c.jobId());jdbc.update("UPDATE integration.carrier_booking SET version=version+1,updated_at=?,updated_by='integration-carrier-tracking' WHERE id=?",stamp(clock.instant()),c.bookingId());audit(c,"ACK_PENDING");return Optional.of(claim(jdbc.queryForMap("SELECT * FROM integration.carrier_booking WHERE id=?",c.bookingId()),jdbc.queryForMap("SELECT * FROM integration.integration_job WHERE id=?",c.jobId())));});}
 private void release(Claim c,String error,String terminal){boolean delivered="DELIVERED".equals(terminal),cancelled="CANCELLED".equals(terminal);jdbc.update("UPDATE integration.carrier_booking SET lease_until=NULL,next_poll_at=?,error_code=?,state=?,last_provider_status=COALESCE(?,last_provider_status),version=version+1,updated_at=?,updated_by='integration-carrier-tracking' WHERE id=?",delivered||cancelled?null:stamp(clock.instant().plusSeconds(900)),error,cancelled?"CANCELLED":"BOOKED",terminal,stamp(clock.instant()),c.bookingId());jdbc.update("UPDATE integration.integration_job SET version=version+1,updated_at=?,updated_by='integration-carrier-tracking' WHERE id=?",stamp(clock.instant()),c.jobId());audit(c,error==null?terminal==null?"UNCHANGED":"ACKNOWLEDGED":"UNAVAILABLE");}
 public boolean failed(Claim c){return Boolean.TRUE.equals(tx.execute(status->{if(!lock(c))return false;release(c,c.compatible()?"PROVIDER_UNAVAILABLE":"PROVIDER_MODE_MISMATCH",null);return true;}));}
 public boolean acknowledged(Claim c,CarrierContextClient.Acknowledgement ack){if(!c.compatible()||ack==null)throw CarrierValues.rule();return Boolean.TRUE.equals(tx.execute(status->{if(!lock(c))return false;var cursor=(ObjectNode)c.checkpoint();var tracking=(ObjectNode)cursor.path("tracking");var body=tracking.path("pending");if(!validTracking(tracking)||!body.isObject()||!c.tracking().equals(body.path("reference").asString())||!c.mode().equals(body.path("mode").asString()))throw CarrierValues.rule();String terminal=body.path("status").asString();if(Set.of("DELIVERED","CANCELLED").contains(terminal)&&!terminal.equals(ack.status()))throw CarrierValues.rule();tracking.remove("pending");tracking.set("last",EventCodec.JSON.valueToTree(Map.of("status",terminal,"occurredAt",body.path("occurredAt").asString())));jdbc.update("UPDATE integration.integration_job SET cursor=?::jsonb WHERE id=?",EventCodec.JSON.writeValueAsString(cursor),c.jobId());release(c,null,terminal);return true;}));}
}
